<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
require dirname(__DIR__).'/src/catalog.php';
start_session();
$pdo=db(); migrate($pdo); migrate_catalog($pdo);
$pdo->exec("CREATE TABLE IF NOT EXISTS knowledge_nodes (id INTEGER PRIMARY KEY AUTOINCREMENT,parent_id INTEGER REFERENCES knowledge_nodes(id),title TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0, UNIQUE(parent_id,title))");
$pdo->exec("CREATE TABLE IF NOT EXISTS knowledge_entries (id INTEGER PRIMARY KEY AUTOINCREMENT,node_id INTEGER NOT NULL REFERENCES knowledge_nodes(id),title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',ap1 INTEGER NOT NULL DEFAULT 0,ap2 INTEGER NOT NULL DEFAULT 0,book TEXT NOT NULL DEFAULT '',page TEXT NOT NULL DEFAULT '',origin_question_id TEXT UNIQUE,author_id INTEGER REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)");
$pdo->exec("CREATE TABLE IF NOT EXISTS knowledge_attachments (id INTEGER PRIMARY KEY AUTOINCREMENT,entry_id INTEGER NOT NULL REFERENCES knowledge_entries(id),stored_name TEXT NOT NULL,original_name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL)");
// Backwards-compatible: imported questions remain plain text.
$knowledgeColumns=$pdo->query("PRAGMA table_info(knowledge_entries)")->fetchAll(PDO::FETCH_ASSOC);
if(!in_array('body_format',array_column($knowledgeColumns,'name'),true))$pdo->exec("ALTER TABLE knowledge_entries ADD COLUMN body_format TEXT NOT NULL DEFAULT 'plain'");
function knowledge_clean_html(string $html):string {
 if(!class_exists('DOMDocument'))return nl2br(htmlspecialchars(strip_tags($html),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'));
 $dom=new DOMDocument('1.0','UTF-8');$old=libxml_use_internal_errors(true);
 $dom->loadHTML('<?xml encoding="UTF-8"?><div id="knowledge-root">'.$html.'</div>',LIBXML_HTML_NOIMPLIED|LIBXML_HTML_NODEFDTD);
 libxml_clear_errors();libxml_use_internal_errors($old);
 $root=$dom->getElementsByTagName('div')->item(0);if(!$root)return '';
 $allowed=['p','br','strong','b','em','i','u','s','ul','ol','li','h2','h3','h4','blockquote','pre','code','sub','sup','div','span'];
 $walk=function($parent)use(&$walk,$allowed){
  $child=$parent->firstChild;
  while($child){
   $next=$child->nextSibling;
   if($child instanceof DOMElement){
    $tag=strtolower($child->tagName);
    if(in_array($tag,['script','style','iframe','object','embed','svg','math','form','input','button','textarea','select','img','video','audio'],true)){$parent->removeChild($child);$child=$next;continue;}
    $walk($child);
    if(!in_array($tag,$allowed,true)){while($child->firstChild)$parent->insertBefore($child->firstChild,$child);$parent->removeChild($child);}
    else {while($child->attributes->length)$child->removeAttributeNode($child->attributes->item(0));}
   }elseif($child instanceof DOMComment){$parent->removeChild($child);}
   $child=$next;
  }
 };
 $walk($root);$result='';foreach($root->childNodes as $child)$result.=$dom->saveHTML($child);return $result;
}
$pdo->exec("CREATE INDEX IF NOT EXISTS idx_knowledge_nodes_parent ON knowledge_nodes(parent_id)");
$pdo->exec("CREATE INDEX IF NOT EXISTS idx_knowledge_entries_node ON knowledge_entries(node_id)");
function node(PDO $db,string $title,?int $parent=null):int {
 $s=$db->prepare('SELECT id FROM knowledge_nodes WHERE title=? AND parent_id IS ?');$s->execute([$title,$parent]);$id=$s->fetchColumn();if($id)return (int)$id;
 $s=$db->prepare('INSERT INTO knowledge_nodes(parent_id,title) VALUES(?,?)');$s->execute([$parent,$title]);return (int)$db->lastInsertId();
}
$roots=['elektro'=>'Elektrotechnik','metall'=>'Metalltechnik','pneu'=>'Pneumatik','sps'=>'SPS'];
foreach($roots as $key=>$title)node($pdo,$title);
$modules=$pdo->query("SELECT m.id,m.title,m.subject_id FROM learning_modules m WHERE m.status='active'")->fetchAll();
foreach($modules as $m){$subject=$roots[$m['subject_id']]??ucfirst((string)$m['subject_id']);$root=node($pdo,$subject);node($pdo,$m['title'],$root);}
$questions=$pdo->query("SELECT q.id,q.title,q.prompt,q.solution_explanation,q.exam_part,m.title AS module_title,m.subject_id FROM learning_questions q JOIN learning_modules m ON m.id=q.module_id WHERE q.status='active' AND m.status='active'")->fetchAll();
$insert=$pdo->prepare("INSERT OR IGNORE INTO knowledge_entries(node_id,title,body,ap1,ap2,origin_question_id) VALUES(?,?,?,?,?,?)");
foreach($questions as $q){$root=node($pdo,$roots[$q['subject_id']]??ucfirst((string)$q['subject_id']));$n=node($pdo,$q['module_title'],$root);$title=trim($q['title'])?:mb_substr($q['prompt'],0,100);$body=$q['prompt'].($q['solution_explanation']?"\n\nErklärung: ".$q['solution_explanation']:'');$insert->execute([$n,$title,$body,str_contains(strtoupper($q['exam_part']),'AP1')?1:0,str_contains(strtoupper($q['exam_part']),'AP2')?1:0,$q['id']]);}
if(!isset($_SESSION['uid'])){http_response_code(401);exit('Bitte zuerst auf MechaTraining anmelden.');}
$uid=(int)$_SESSION['uid'];$role=$_SESSION['role']??'student';$edit=in_array($role,['admin','editor'],true);
if(isset($_GET['file'])){$id=(int)$_GET['file'];$s=$pdo->prepare('SELECT a.* FROM knowledge_attachments a WHERE a.id=?');$s->execute([$id]);$a=$s->fetch();if(!$a) {http_response_code(404);exit;} $path=dirname(__DIR__).'/storage/knowledge/'.$a['stored_name'];if(!is_file($path)){http_response_code(404);exit;}header('Content-Type: '.$a['mime']);header('X-Content-Type-Options: nosniff');header('Content-Disposition: attachment; filename="'.str_replace('"','',basename($a['original_name'])).'"');readfile($path);exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
 header('Content-Type: application/json; charset=utf-8');
 if(!$edit){http_response_code(403);exit(json_encode(['error'=>'Keine Berechtigung']));}
 if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(403);exit(json_encode(['error'=>'Sitzung ungültig']));}
 try{
 $act=$_POST['action']??'';
 if($act==='node'){$parent=($_POST['parent']??'')!==''?(int)$_POST['parent']:null;$title=trim((string)($_POST['title']??''));if(!$title||mb_strlen($title)>150)throw new Exception('Ungültiger Titel');if($parent){$s=$pdo->prepare('SELECT 1 FROM knowledge_nodes WHERE id=?');$s->execute([$parent]);if(!$s->fetchColumn())throw new Exception('Übergeordnetes Thema fehlt');}$id=node($pdo,$title,$parent);}
 elseif($act==='entry'){$title=trim((string)($_POST['title']??''));$body=knowledge_clean_html(trim((string)($_POST['body']??'')));$nodeId=(int)($_POST['node']??0);if(!$title||!$nodeId)throw new Exception('Titel und Thema erforderlich');$book=(string)($_POST['book']??'');if(!in_array($book,['','metall','elektro'],true))throw new Exception('Ungültiges Buch');$id=(int)($_POST['id']??0);
 if($id){$s=$pdo->prepare('UPDATE knowledge_entries SET node_id=?,title=?,body=?,body_format=\'html\',ap1=?,ap2=?,book=?,page=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$s->execute([$nodeId,$title,$body,isset($_POST['ap1'])?1:0,isset($_POST['ap2'])?1:0,$book,substr((string)($_POST['page']??''),0,40),$id]);}
 else{$s=$pdo->prepare('INSERT INTO knowledge_entries(node_id,title,body,ap1,ap2,book,page,author_id,body_format) VALUES(?,?,?,?,?,?,?,?,\'html\')');$s->execute([$nodeId,$title,$body,isset($_POST['ap1'])?1:0,isset($_POST['ap2'])?1:0,$book,substr((string)($_POST['page']??''),0,40),$uid]);$id=(int)$pdo->lastInsertId();}
 if(isset($_FILES['files'])){ $dir=dirname(__DIR__).'/storage/knowledge';if(!is_dir($dir))mkdir($dir,0700,true);foreach($_FILES['files']['error'] as $i=>$err){if($err===UPLOAD_ERR_NO_FILE)continue;if($err!==UPLOAD_ERR_OK)throw new Exception('Upload fehlgeschlagen');$tmp=$_FILES['files']['tmp_name'][$i];$size=(int)$_FILES['files']['size'][$i];if($size>15*1024*1024)throw new Exception('Datei über 15 MB');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$allowed=['application/pdf'=>'pdf','image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))throw new Exception('Nur PDF, JPG, PNG und WebP');$name=bin2hex(random_bytes(16)).'.'.$allowed[$mime];if(!move_uploaded_file($tmp,$dir.'/'.$name))throw new Exception('Speichern fehlgeschlagen');$s=$pdo->prepare('INSERT INTO knowledge_attachments(entry_id,stored_name,original_name,mime,size) VALUES(?,?,?,?,?)');$s->execute([$id,$name,basename($_FILES['files']['name'][$i]),$mime,$size]);}}}
 else throw new Exception('Unbekannte Aktion');
 echo json_encode(['ok'=>true,'id'=>$id]);exit;
 }catch(Throwable $e){http_response_code(422);exit(json_encode(['error'=>$e->getMessage()]));}
}
// Keep archived SPS knowledge and IDs in SQLite, but hide them from the visible tree.
$hiddenSpsModules=$pdo->query("SELECT DISTINCT m.title FROM learning_modules m WHERE m.id IN ('elektro:sps-grundlagen','elektro:sps-logik','elektro:sps-zeiten') AND m.status='archived'")->fetchAll(PDO::FETCH_COLUMN);
$nodes=$pdo->query('SELECT * FROM knowledge_nodes ORDER BY sort_order,title')->fetchAll();
$hiddenNodeIds=[];
foreach($nodes as $n){
 if(($n['title']==='SPS' && $n['parent_id']===null) || in_array($n['title'],$hiddenSpsModules,true))$hiddenNodeIds[]=(int)$n['id'];
}
$nodes=array_values(array_filter($nodes,static fn($n)=>!in_array((int)$n['id'],$hiddenNodeIds,true)));
$entries=$pdo->query("SELECT k.* FROM knowledge_entries k LEFT JOIN learning_questions q ON q.id=k.origin_question_id WHERE (k.origin_question_id IS NULL OR q.id IS NULL OR q.status='active') ORDER BY k.title")->fetchAll();
$entries=array_values(array_filter($entries,static fn($e)=>!in_array((int)$e['node_id'],$hiddenNodeIds,true)));
$assets=$pdo->query('SELECT id,entry_id,original_name FROM knowledge_attachments')->fetchAll();
$csrf=htmlspecialchars($_SESSION['csrf']??'',ENT_QUOTES);
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wissensbank – MechaTraining</title><style>
:root{color-scheme:light;font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:#f7f9fc;color:#18283b}*{box-sizing:border-box}body{margin:0;background:#f7f9fc;color:#18283b;font-size:16px;line-height:1.55}header{padding:17px max(20px,calc((100vw - 1100px)/2));border-bottom:1px solid #dbe4ed;background:#fff;display:flex;justify-content:space-between;align-items:center;gap:16px}a{color:#1369b4}a:hover{text-decoration:underline}main{min-height:80vh}section{padding:24px;min-width:0}button,input,textarea,select{font:inherit}button{cursor:pointer;background:#eef4fa;color:#193c5c;border:1px solid #c5d5e4;border-radius:9px;padding:9px 13px}button:hover{background:#dceaf6}button:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #438cd4;outline-offset:2px}input,textarea,select{width:100%;padding:11px;border:1px solid #b7c9d8;border-radius:9px;background:#fff;color:#17283a}input::placeholder{color:#64788b}label{display:block;margin:12px 0 5px}textarea{min-height:160px}details{margin:7px 0 7px 12px}summary{cursor:pointer;padding:6px}.entry{position:relative;overflow-wrap:anywhere;background-color:#fff;padding:20px;border:solid 1px #c2c2c2;margin-bottom:20px;border-radius:10px}.entry h3{margin:0 0 9px;font-size:1.18rem;line-height:1.4;overflow-wrap:anywhere}.entry p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.65;max-width:800px}.muted{font-size:.9rem;margin:10px 0;position:absolute;top:10px;right:10px;background:#4b7fcf;color:#fff;padding:1px 5px;border-radius:4px}.fab{position:fixed;right:22px;bottom:22px;border-radius:50%;background:#176fc1;color:#fff;border-color:#176fc1;font-size:28px;width:58px;height:58px;box-shadow:0 5px 18px #0d3d6a33}.fab:hover{background:#105a9f}dialog{background:#fff;color:#18283b;border:1px solid #c8d7e4;border-radius:14px;width:min(620px,94vw);max-height:90vh;overflow:auto;box-shadow:0 20px 60px #20344840}dialog::backdrop{background:#20344888}dialog form{padding:8px}dialog .checks{display:flex;gap:25px}.checks label{display:flex;gap:7px;align-items:center}.checks input{width:auto}.actions{display:flex;gap:10px;margin-top:20px}.search{margin-bottom:18px}.knowledge-toolbar{display:flex;align-items:center;gap:15px;padding:12px max(20px,calc((100vw - 1100px)/2));border-bottom:1px solid #dbe4ed;background:#fff}.knowledge-toolbar button{display:flex;align-items:center;gap:8px;font-weight:700}.knowledge-toolbar #topicLocation{color:#506579;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}#knowledgeLayout{display:block;min-height:80vh}#knowledgeLayout>section{max-width:1100px;margin:auto}#knowledgeLayout h1{font-size:clamp(1.6rem,3vw,2.2rem);line-height:1.2}.tree-sidebar{position:fixed;z-index:30;top:0;bottom:0;left:0;width:min(340px,88vw);background:#fff;border-right:1px solid #dbe4ed;box-shadow:12px 0 32px #20344833;overflow:auto;transform:translateX(-105%);visibility:hidden;transition:transform .2s ease,visibility .2s;padding:18px}.tree-sidebar.is-open{transform:translateX(0);visibility:visible}.tree-head{display:flex;align-items:center;justify-content:space-between;gap:12px}.tree-head h2{margin:0}.tree-head button{padding:7px 11px}.tree-backdrop:not([hidden]){position:fixed;inset:0;z-index:29;background:#20344866;display:block}@media(max-width:700px){#knowledgeLayout>section{padding:18px}.knowledge-toolbar{padding:10px 16px}header{padding:14px 16px}.entry{padding:20px}}@media(prefers-reduced-motion:reduce){.tree-sidebar{transition:none}}
.rich-toolbar{display:flex;gap:5px;flex-wrap:wrap;background:#eef4fa;border:1px solid #b7c9d8;border-radius:9px 9px 0 0;padding:8px}.rich-toolbar button{background:#fff;padding:6px 10px}.rich-editor{background:#fff;color:#18283b;border:1px solid #b7c9d8;border-top:0;border-radius:0 0 9px 9px;padding:14px;min-height:220px;overflow-wrap:anywhere;outline-offset:2px}.rich-editor p{margin:.5em 0}.knowledge-content{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.65;max-width:800px}.knowledge-content p{margin:.6em 0}.knowledge-content ul,.knowledge-content ol{padding-left:1.6em}.knowledge-content pre{white-space:pre-wrap;overflow-wrap:anywhere}.entry h3{padding-right:90px}
.tree-leaf{display:block;width:100%;text-align:left;border:0;background:transparent;color:inherit;font:inherit;cursor:pointer;padding:6px 8px 6px 25px}.tree-leaf:hover,.tree-leaf:focus-visible{background:#edf4fa;border-radius:6px}</style></head><body><header><strong>MECHATRaining · Wissensbank</strong><a href="./">Zur Startseite</a></header><div class="knowledge-toolbar"><button id="treeToggle" type="button" aria-controls="topicSidebar" aria-expanded="false">☰ <span>Themen</span></button><span id="topicLocation">Alle Wissenseinträge</span></div><div id="treeBackdrop" class="tree-backdrop" hidden></div><main id="knowledgeLayout"><aside id="topicSidebar" class="tree-sidebar" aria-label="Themennavigation"><div class="tree-head"><h2>Themenbaum</h2><button type="button" id="treeClose" aria-label="Themennavigation schließen">✕</button></div><div id="tree"></div><?php if($edit):?><button id="addNode">+ Unterthema</button><?php endif;?></aside><section><h1 id="heading">Alle Wissenseinträge</h1><input class="search" id="search" type="search" placeholder="Wissen durchsuchen …"><div id="entries"></div></section></main><?php if($edit):?><button class="fab" id="addEntry" title="Wissen erfassen">+</button><dialog id="editor"><form id="entryForm" enctype="multipart/form-data"><h2>Wissen erfassen</h2><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="entry"><input type="hidden" name="id" id="entryId"><label>Thema<select name="node" id="nodeSelect" required></select></label><label>Titel<input name="title" required maxlength="200"></label><label for="richBody">Inhalt / Formeln</label><div class="rich-toolbar" role="toolbar" aria-label="Textformatierung"><button type="button" data-command="bold" title="Fett"><strong>F</strong></button><button type="button" data-command="italic" title="Kursiv"><em>K</em></button><button type="button" data-command="underline" title="Unterstreichen"><u>U</u></button><button type="button" data-command="insertUnorderedList">• Liste</button><button type="button" data-command="insertOrderedList">1. Liste</button><button type="button" data-block="h3">Überschrift</button><button type="button" data-block="p">Absatz</button><button type="button" data-command="removeFormat">Format entfernen</button></div><div id="richBody" class="rich-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-label="Inhalt mit Formatierung"></div><input type="hidden" name="body" id="bodyHtml"><div class="checks"><label><input type="checkbox" name="ap1"> AP1</label><label><input type="checkbox" name="ap2"> AP2</label></div><label>Tabellenbuch<select name="book"><option value="">Keine Angabe</option><option value="metall">Tabellenbuch Metall · 978-3758514715</option><option value="elektro">Tabellenbuch Elektrotechnik · 978-3758533174</option></select></label><label>Seite<input name="page" placeholder="z. B. 94"></label><label>Anhänge (PDF / Fotos, je 15 MB)<input type="file" name="files[]" multiple accept=".pdf,image/jpeg,image/png,image/webp" capture="environment"></label><div class="actions"><button type="submit">Speichern</button><button type="button" id="cancel">Abbrechen</button></div><p id="error" role="alert"></p></form></dialog><?php endif;?><script>
const nodes=<?=json_encode($nodes,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>, entries=<?=json_encode($entries,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>,assets=<?=json_encode($assets,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;
let selected=null;const tree=document.querySelector('#tree'),list=document.querySelector('#entries'),search=document.querySelector('#search');const byId=new Map(nodes.map(n=>[Number(n.id),n]));function descendants(id){let ids=new Set([id]);let changed=true;while(changed){changed=false;for(const n of nodes)if(ids.has(Number(n.parent_id))&&!ids.has(Number(n.id))){ids.add(Number(n.id));changed=true}}return ids}
function drawTree(parent,container){for(const n of nodes.filter(x=>Number(x.parent_id||0)===Number(parent||0))){const children=nodes.filter(x=>Number(x.parent_id)===Number(n.id));const hasChildren=children.length>0;const d=document.createElement(hasChildren?'details':'div');if(hasChildren)d.open=parent===null;const s=document.createElement(hasChildren?'summary':'button');if(!hasChildren){s.type='button';s.className='tree-leaf';}s.textContent=n.title;s.onclick=()=>{selected=Number(n.id);document.querySelector('#heading').textContent=n.title;document.querySelector('#topicLocation').textContent=n.title;closeTree();render()};d.append(s);if(hasChildren)drawTree(Number(n.id),d);container.append(d)}}
function render(){list.replaceChildren();const q=search.value.toLocaleLowerCase('de');const allowed=selected===null?null:descendants(selected);const filtered=entries.filter(e=>(!allowed||allowed.has(Number(e.node_id)))&&(e.title+' '+e.body).toLocaleLowerCase('de').includes(q));for(const e of filtered){const div=document.createElement('article');div.className='entry';const h=document.createElement('h3');h.textContent=e.title;div.append(h);const p=document.createElement('div');p.className='knowledge-content';if(e.body_format==='html')p.innerHTML=e.body;else p.textContent=e.body;div.append(p);const m=document.createElement('div');m.className='muted';m.textContent=[e.ap1==1?'AP1':'',e.ap2==1?'AP2':'',e.book==='metall'?'Tabellenbuch Metall':e.book==='elektro'?'Tabellenbuch Elektrotechnik':'',e.page?'S. '+e.page:''].filter(Boolean).join(' · ');div.append(m);for(const a of assets.filter(a=>Number(a.entry_id)===Number(e.id))){const link=document.createElement('a');link.href='?file='+encodeURIComponent(a.id);link.textContent='📎 '+a.original_name;link.style.display='block';div.append(link)}<?php if($edit):?>const b=document.createElement('button');b.textContent='Bearbeiten';b.onclick=()=>openEditor(e);div.append(b);<?php endif;?>list.append(div)}if(!filtered.length)list.textContent='Keine Einträge gefunden.'}
const sidebar=document.querySelector('#topicSidebar'),toggle=document.querySelector('#treeToggle'),backdrop=document.querySelector('#treeBackdrop');function closeTree(){sidebar.classList.remove('is-open');toggle.setAttribute('aria-expanded','false');backdrop.hidden=true;}function openTree(){sidebar.classList.add('is-open');toggle.setAttribute('aria-expanded','true');backdrop.hidden=false;}toggle.addEventListener('click',()=>sidebar.classList.contains('is-open')?closeTree():openTree());document.querySelector('#treeClose').addEventListener('click',closeTree);backdrop.addEventListener('click',closeTree);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeTree()});drawTree(null,tree);search.oninput=render;render();
<?php if($edit):?>const dialog=document.querySelector('#editor'),form=document.querySelector('#entryForm'),sel=document.querySelector('#nodeSelect');for(const n of nodes){const opt=document.createElement('option');opt.value=n.id;let chain=[],cur=n;while(cur){chain.unshift(cur.title);cur=byId.get(Number(cur.parent_id))}opt.textContent=chain.join(' / ');sel.append(opt)}
const rich=document.querySelector('#richBody');function plainHtml(t){const el=document.createElement('div');el.textContent=t||'';return el.innerHTML.replace(/\n/g,'<br>')}function openEditor(e){form.reset();rich.innerHTML='';document.querySelector('#entryId').value=e?.id||'';if(e){sel.value=e.node_id;form.elements.title.value=e.title;rich.innerHTML=e.body_format==='html'?e.body:plainHtml(e.body);form.elements.ap1.checked=!!Number(e.ap1);form.elements.ap2.checked=!!Number(e.ap2);form.elements.book.value=e.book;form.elements.page.value=e.page}else if(selected)sel.value=selected;dialog.showModal()}
document.querySelector('#addEntry').onclick=()=>openEditor(null);document.querySelector('#cancel').onclick=()=>dialog.close();document.querySelectorAll('.rich-toolbar button').forEach(b=>b.addEventListener('click',()=>{rich.focus();document.execCommand(b.dataset.block?'formatBlock':b.dataset.command,false,b.dataset.block||null)}));form.onsubmit=async ev=>{ev.preventDefault();document.querySelector('#bodyHtml').value=rich.innerHTML;const res=await fetch('wissen.php',{method:'POST',body:new FormData(form)});const data=await res.json();if(data.ok)location.reload();else document.querySelector('#error').textContent=data.error||'Fehler'};
document.querySelector('#addNode').onclick=async()=>{const title=prompt('Name des neuen Unterthemas:');if(!title?.trim())return;const fd=new FormData();fd.set('csrf',form.elements.csrf.value);fd.set('action','node');fd.set('title',title.trim());if(selected)fd.set('parent',selected);const r=await fetch('wissen.php',{method:'POST',body:fd});const d=await r.json();if(d.ok)location.reload();else alert(d.error)};
<?php endif;?>
</script></body></html>